mapper.select:
SELECT  FROM rule
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT  FROM rule r
WHERE r.created_by_id = #{userId}
   OR r.run_as_user_id = #{userId}
   OR EXISTS (
     SELECT 1 FROM workflow w
     WHERE w.workspace_id = r.workspace_id
       AND w.legacy_rule_id = r.id
       AND (w.created_by_id = #{userId}
         OR w.updated_by_id = #{userId}
         OR w.draft_run_as_user_id = #{userId}
         OR EXISTS (
           SELECT 1 FROM workflow_version v
           WHERE v.workspace_id = w.workspace_id
             AND v.workflow_id = w.id
             AND v.id = w.active_version_id
             AND (v.created_by_id = #{userId}
               OR v.published_by_id = #{userId}
               OR v.run_as_user_id = #{userId})
         ))
   )
ORDER BY r.workspace_id, r.id

mapper.update:
UPDATE rule
SET name = #{name}, description = #{description}, enabled = #{enabled},
    record_type = #{recordType}, trigger_type = #{triggerType},
    trigger_config = #{triggerConfig}, condition_json = #{conditionJson},
    actions_json = #{actionsJson}, execution_mode = #{executionMode}, run_as_user_id = #{runAsUserId}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE rule
SET run_as_user_id = IF(run_as_user_id = #{userId}, NULL, run_as_user_id),
    created_by_id = IF(created_by_id = #{userId}, NULL, created_by_id)
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND (run_as_user_id = #{userId} OR created_by_id = #{userId})

mapper.select:
SELECT id, workspace_id, rule_id, trigger_entity_type, trigger_entity_id,
  status, dedupe_key, detail, executed_at
FROM rule_execution
WHERE workspace_id = #{workspaceId}
  AND rule_id = #{ruleId}
  AND dedupe_key = #{dedupeKey}

SELECT id, workspace_id, rule_id, trigger_entity_type, trigger_entity_id,
  status, dedupe_key, detail, executed_at
FROM rule_execution
WHERE workspace_id = #{workspaceId}
  AND rule_id = #{ruleId}
  AND id = #{id}

SELECT id, workspace_id, rule_id, trigger_entity_type, trigger_entity_id,
  status, dedupe_key, detail, executed_at
FROM rule_execution
WHERE workspace_id = #{workspaceId}
  AND rule_id = #{ruleId}
  AND executed_at <= #{asOf}

    AND (executed_at < #{beforeExecutedAt}
      OR (executed_at = #{beforeExecutedAt} AND id < #{beforeId}))

ORDER BY executed_at DESC, id DESC
LIMIT #{limit}

SELECT id, workspace_id, rule_id, trigger_entity_type, trigger_entity_id, status, dedupe_key, detail, executed_at
FROM rule_execution
WHERE workspace_id = #{workspaceId} AND rule_id = #{ruleId}
ORDER BY executed_at DESC, id DESC
LIMIT #{limit}
